type xsd:decimal ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <http://qudt.org/schema/qudt/numericValue> ], [ sh:hasValue <http://qudt.org/vocab/unit/MegaN> ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <http://qudt.org/schema/qudt/unit> ] ] ; sh:path <https://w3id.org/nltl/vocab#bowDesignForceMethodI2Point3Point2Point1PartIv> ], [ sh:minCount Literal("1", datatype=xsd:integer) ; sh:node [ sh:property [ sh:datatype xsd:decimal ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <http://qudt.org/schema/qudt/numericValue> ], [ sh:hasValue <http://qudt.org/vocab/unit/UNITLESS> ; sh:maxCount Literal("1", datatype=xsd:integer) ; sh:minCount Literal("1", datatype=xsd:integer) ; sh:path <http://qudt.org/schema/qudt/unit> ] ] ; sh:path <https://w3id.org/nltl/vocab#shapeCoefficient> ] ; sh:sparql [ sh:message Literal("For an applicable PC6 or PC7 ship with a bulbous bow, the bow design force must correspond to the force determined under I2.3.2.1(iv), within a relative tolerance of 1e-6 with a small absolute fallback, and must not be less than the I2.3.2.1(iii) force.") ; sh:select Literal("
                    PREFIX nltl: <https://w3id.org/nltl/vocab#>
                    PREFIX q: <http://qudt.org/schema/qudt/>
                    PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

                    SELECT $this
                    WHERE {
                        $this nltl:polarClass ?pc ;
                              nltl:bulbousBowPresent true ;
                              nltl:bowDesignForce ?result ;
                              nltl:bowDesignForceMethodI2Point3Point2Point1PartIii ?partIii ;
                              nltl:bowDesignForceMethodI2Point3Point2Point1PartIv ?partIv .

                        FILTER (
                            ?pc = nltl:polarClassPc6 ||
                            ?pc = nltl:polarClassPc7
                        )

                        ?result q:numericValue ?resultValue ;
                                q:unit <http://qudt.org/vocab/unit/KiloN> .
                        ?partIii q:numericValue ?partIiiValue ;
                                 q:unit <http://qudt.org/vocab/unit/MegaN> .
                        ?partIv q:numericValue ?partIvValue ;
                                q:unit <http://qudt.org/vocab/unit/MegaN> .

                        BIND (?partIvValue * 1000 AS ?expectedValue)
                        FILTER (
                            ?resultValue < ?partIiiValue * 1000 ||
                            ABS(?resultValue - ?expectedValue) >
                                (ABS(?expectedValue) * 0.000001 + 0.000001)
                        )
                    }
                ") ] ] , [ sh:or ( [ sh:property [ sh:hasValue Literal("false" = False, datatype=xsd:boolean) ; sh:path <https://w3id.org/nltl/vocab#bulbousBowPresent> ] ] [ sh:property [ sh:in ( <https://w3id.org/nltl/vocab#polarClassPc1> <https://w3id.org/nltl/vocab#polarClassPc2> <https://w3id.org/nltl/vocab#polarClassPc3> <https://w3id.org/nltl/vocab#polarClassPc4> <https://w3id.org/nltl/vocab#polarClassPc5> ) ; sh:path <https://w3id.org/nltl/vocab#polarClass> ] ] ) ]

